// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        vm.warp(seed % 10000);
        vm.roll(1 + (seed >> 32) % 10000);

        vm.deal(actor, 1000 ether);
        uint256 potBefore = c.pot();
        uint256 balBefore = actor.balance;

        vm.prank(actor);
        c.play{value: 10}();

        // General rule: if this play was a win (pot was reset to 0), the winner
        // received exactly potBefore - FEE_AMOUNT (1 wei). P always satisfies
        // this; M pays the full pot and violates it whenever a win occurs.
        assertTrue(
            c.pot() != 0 || (actor.balance == balBefore + potBefore - 1),
            "winner must receive pot minus the fee"
        );
    }
}

