pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    receive() external payable {}

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(actor.code.length == 0); // plain recipient that accepts ETH transfers
        ts = bound(ts, 0, 2 ** 64 - 1);

        vm.deal(actor, 1 ether);
        vm.warp(ts);

        uint256 playerBefore = actor.balance;
        uint256 bankBefore = address(this).balance;

        vm.prank(actor);
        c.play{value: 10}();

        uint256 playerDelta = actor.balance - playerBefore;
        uint256 bankDelta = address(this).balance - bankBefore;

        // Conservation: ticket value 10 must split between player and bank.
        assertTrue(playerDelta + bankDelta == 10);
    }
}

