pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 ts, uint256 diff, address actor) public {
        // Keep the randomness domain wide: only require this seed is a WINNING seed.
        vm.warp(ts);
        vm.roll(diff);
        vm.assume(
            uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 == 0
        );
        // The player must be a plain account so the payout transfer succeeds (EOA accepts ETH).
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(0));

        vm.deal(actor, 10); // exactly one ticket (10 wei)

        uint256 potBefore = c.pot(); // == TICKET_AMOUNT = 10

        vm.prank(actor);
        c.play{value: 10}();

        // General rule: after a winning play the winner holds exactly
        // pot_before - FEE_AMOUNT (the 1-wei fee went to the bank) and the pot is empty.
        assertTrue(
            actor.balance == potBefore - 1 && c.pot() == 0 && address(c).balance == 0,
            "winner must receive pot minus the fee"
        );
    }
}

