pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Picky picky;

    function setUp() public {
        c = new C();
        picky = new Picky();
    }

    function testFuzz_property(uint256 ts, uint256 diff) public {
        ts = bound(ts, 1, type(uint64).max);
        diff = bound(diff, 0, type(uint64).max);
        vm.warp(ts);
        vm.roll(diff);
        vm.deal(address(picky), 10);
        bool ok;
        vm.prank(address(picky));
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a winning play must succeed when the winner accepts
        // any payout of pot - FEE_AMOUNT; it never reverts on the reference.
        assertTrue(ok, "play reverted");
    }
}

contract Picky {
    // Accepts only payouts of at most 9 wei (i.e. pot - FEE_AMOUNT when pot = 10).
    receive() external payable {
        require(msg.value <= 9);
    }
}

