pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 tsBase, address actor) public {
        vm.assume(actor != address(0) && actor != c.bank());
        // find a timestamp (searched from the fuzzed base) at which the round is a WIN
        uint256 winTs;
        bool found = false;
        for (uint256 i = 0; i < 256; i++) {
            uint256 t = tsBase + i;
            if (uint256(keccak256(abi.encodePacked(t, block.difficulty))) % 2 == 0) {
                winTs = t;
                found = true;
                break;
            }
        }
        vm.assume(found);

        address bank = c.bank();
        uint256 bankBefore = bank.balance;

        vm.warp(winTs);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.play{value: 10}();

        // General rule: a completed winning round resets the pot AND pays the bank the fee of 1 wei.
        assertTrue(c.pot() == 0 && bank.balance == bankBefore + 1);
    }
}

