pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, address actor) public {
        // Admissible domain: actor must be a plain recipient able to accept ETH,
        // seed only shapes the winning randomness via warp/roll.
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 0xff);
        vm.assume(actor != address(c));

        // Shape the winning randomness through the fuzzed seed.
        vm.warp(seed);
        vm.roll(seed);

        uint256 bankBefore = c.bank().balance;
        uint256 ticket = 10; // TICKET_AMOUNT required by play()

        vm.deal(actor, ticket);
        vm.prank(actor);
        c.play{value: ticket}();

        // General rule: if this call was a winning round (pot reset to 0),
        // the bank must have been paid exactly FEE_AMOUNT (1 wei).
        bool ok = (c.pot() != 0) || (c.bank().balance == bankBefore + 1);
        assertTrue(ok);
    }
}

