        vm.prank(address(bankAccount));
        c = new C();
    }

    function testFuzz_property(uint256 t) public {
        t = bound(t, 1, type(uint128).max);
        vm.warp(t);

        uint potBefore = c.pot();
        uint bankBefore = address(c.bank()).balance;

        // the bank itself plays one round with the exact ticket price
        vm.deal(address(bankAccount), 10);
        vm.prank(address(bankAccount));
        c.play{value: 10}();

        bool won = (c.pot() == 0); // a winning round resets pot to 0
        uint bankDelta = address(c.bank()).balance - bankBefore;

        assertTrue(!won || bankDelta == 1);
    }
}

