pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0));
        vm.warp(ts);

        vm.deal(actor, 10);
        vm.startPrank(actor);
        bool ok;
        uint256 balanceBefore = address(c).balance;
        uint256 potBefore = c.pot();
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        if (ok && c.pot() == 0 && potBefore > 0) {
            assertTrue(address(c).balance == balanceBefore - potBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount) public {
        require(address(this).balance >= 2 * amount);

        (bool ok1, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.play.selector));
        require(ok1);

        (bool ok2, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.play.selector));
        assert(ok2);
    }

    receive() external payable {}
    fallback() external payable {}
}

